    if (root == nullptr)
        return true;

    // If leaf node
    if (root->left == nullptr && root->right == nullptr)
    {
        // Store level of first leaf node
        if (leafLevel == -1)
            leafLevel = level;

        // All leaf nodes must be at same level
        return level == leafLevel;
